    status_code = 422
    error_type = "https://ledger.example/errors/validation"
    title = "Validation Error"


class RefundCapExceededError(LedgerError):
    status_code = 422
    error_type = "https://ledger.example/errors/refund-cap-exceeded"
    title = "Refund Exceeds Settled Amount"


def _require_int(value: object, field: str, minimum: int) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValidationError(f"{field} must be an integer in minor units")
    if value < minimum:
        raise ValidationError(f"{field} must be >= {minimum}")
    return value


def _require_bps(rate_bps: Union[Decimal, str, int]) -> Decimal:
    if isinstance(rate_bps, bool):
        raise ValidationError("rate_bps must be Decimal, str, or int")
    if isinstance(rate_bps, float):
        raise ValidationError("float rates are prohibited by ADR-002; pass Decimal, str, or int")
    if not isinstance(rate_bps, (Decimal, str, int)):
        raise ValidationError("rate_bps must be Decimal, str, or int")
    try:
        dec_bps = rate_bps if isinstance(rate_bps, Decimal) else Decimal(str(rate_bps).strip())
    except (InvalidOperation, ValueError) as exc:
        raise ValidationError("rate_bps must be a valid decimal number") from exc
    if not dec_bps.is_finite() or dec_bps < 0:
        raise ValidationError("rate_bps must be a finite non-negative value")
    return dec_bps


def compute_fee_minor(amount_minor: int, rate_bps: Union[Decimal, str, int]) -> int:
    """Compute a basis-points fee as integer minor units with banker's rounding."""
    amount = _require_int(amount_minor, "amount_minor", minimum=0)
    dec_bps = _require_bps(rate_bps)
    raw_fee = (Decimal(amount) * dec_bps) / BPS_DENOMINATOR
    rounded_fee = raw_fee.quantize(Decimal("1"), rounding=ROUND_HALF_EVEN)
    return int(rounded_fee)


def validate_refund_request(
    tenant_id: str,
    idempotency_key: str,
    settled_minor: int,
    already_refunded_minor: int,
    refund_minor: int,
) -> None:
    """Validate tenant context, idempotency key, and cumulative refund conservation."""
    if not isinstance(tenant_id, str) or not tenant_id.strip():
        raise ValidationError("tenant_id is required")

    if not isinstance(idempotency_key, str):
        raise ValidationError("idempotency_key must be a string")
    cleaned_key = idempotency_key.strip()
    if not cleaned_key or len(cleaned_key) > MAX_IDEMPOTENCY_KEY_LENGTH:
        raise ValidationError("idempotency_key must be non-empty and <= 128 chars")

    settled = _require_int(settled_minor, "settled_minor", minimum=1)
    already_refunded = _require_int(already_refunded_minor, "already_refunded_minor", minimum=0)
    refund = _require_int(refund_minor, "refund_minor", minimum=1)

    if already_refunded > settled:
        raise RefundCapExceededError(
            f"Cumulative refunds {already_refunded} already exceed settled amount {settled}"
        )

    remaining_refundable = settled - already_refunded
    if refund > remaining_refundable:
        raise RefundCapExceededError(
            f"Refund of {refund} exceeds remaining refundable balance {remaining_refundable}"
