"""Webhook signature and replay verification conforming to ADR-003."""

from __future__ import annotations

import hashlib
import hmac
import re
import time

MAX_WEBHOOK_DRIFT_SECONDS = 300

_SIGNATURE_PREFIX = "v1="
_SIGNATURE_RE = re.compile(r"[0-9a-f]{64}")
_TIMESTAMP_RE = re.compile(r"[0-9]+")


def _parse_timestamp(timestamp_header: str) -> int | None:
    if not isinstance(timestamp_header, str):
        return None
    candidate = timestamp_header.strip()
    if not _TIMESTAMP_RE.fullmatch(candidate):
        return None
    try:
        return int(candidate)
    except ValueError:
        return None


def _parse_signature(signature_header: str) -> str | None:
    if not isinstance(signature_header, str):
        return None
    candidate = signature_header.strip()
    if not candidate.startswith(_SIGNATURE_PREFIX):
        return None
    digest = candidate[len(_SIGNATURE_PREFIX):].lower()
    if not _SIGNATURE_RE.fullmatch(digest):
        return None
    return digest


def verify_webhook(
    secret: str,
    timestamp_header: str,
    signature_header: str,
    raw_body: bytes,
    now_epoch: int | None = None,
) -> bool:
    if not isinstance(secret, str) or not secret:
        return False

    ts = _parse_timestamp(timestamp_header)
    if ts is None:
        return False

    received_hex = _parse_signature(signature_header)
    if received_hex is None:
        return False

    if isinstance(raw_body, (bytearray, memoryview)):
        body_bytes = bytes(raw_body)
    elif isinstance(raw_body, bytes):
        body_bytes = raw_body
    else:
        return False

    try:
        body_text = body_bytes.decode("utf-8")
    except UnicodeDecodeError:
        return False

    try:
        current = int(time.time()) if now_epoch is None else int(now_epoch)
    except (TypeError, ValueError):
        return False

    if abs(current - ts) > MAX_WEBHOOK_DRIFT_SECONDS:
        return False

    signing_payload = f"{ts}.{body_text}".encode("utf-8")
    expected_hex = hmac.new(
        secret.encode("utf-8"), signing_payload, hashlib.sha256
    ).hexdigest()

    return hmac.compare_digest(expected_hex, received_hex)
