- redact_payload(value): recursively redacts sensitive mapping keys
  (token, secret, api_key, password, authorization, iban, account_number,
  card_number, ssn, tax_id, email, phone) using case-insensitive substring
  matching. Secrets become "***REDACTED***"; bank identifiers keep at most
  their trailing four characters ("****1234").
- build_error_response(...): returns an RFC 9457 problem-details mapping
  (type, title, status, detail, trace_id) with sensitive strings scrubbed
  before serialization.

This module never calls bare print().
"""

from __future__ import annotations

import re
from typing import Any, Mapping

__all__ = ["REDACTED", "mask_last4", "redact_payload", "build_error_response"]

REDACTED = "***REDACTED***"

_MASKABLE_KEYS = ("iban", "accountnumber", "cardnumber")
_SENSITIVE_KEYS = (
    "token",
    "secret",
    "apikey",
    "password",
    "authorization",
    "iban",
    "accountnumber",
    "cardnumber",
    "ssn",
    "taxid",
    "email",
    "phone",
)

_EMAIL_RE = re.compile(r"(?i)\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b")
_LONG_DIGITS_RE = re.compile(r"\b\d(?:[ -]?\d){12,18}\b")

_RESERVED_PROBLEM_KEYS = frozenset({"type", "title", "status", "detail", "trace_id"})
_CONTAINER_TYPES = (Mapping, list, tuple, set, frozenset)


def _normalize_key(key: str) -> str:
    """Lowercase and strip separators so apiKey/API_KEY/api-key all match."""
    return re.sub(r"[^a-z0-9]", "", key.lower())


def _sensitive_kind(key: Any) -> str | None:
    """Return 'mask', 'redact', or None for a mapping key."""
    if not isinstance(key, str):
        return None
    normalized = _normalize_key(key)
    if not normalized:
        return None
    if any(candidate in normalized for candidate in _MASKABLE_KEYS):
        return "mask"
    if any(candidate in normalized for candidate in _SENSITIVE_KEYS):
        return "redact"
    return None


def mask_last4(value: Any) -> str:
    """Preserve only the trailing four characters of an identifier."""
    text = str(value)
    if len(text) <= 4:
        return REDACTED
    return "****" + text[-4:]


def _scrub_text(text: str) -> str:
    """Redact emails and long digit runs (card-like numbers) in free text."""
    text = _EMAIL_RE.sub(REDACTED, text)

    def _mask_match(match: re.Match[str]) -> str:
        digits = re.sub(r"\D", "", match.group(0))
        return mask_last4(digits)

    return _LONG_DIGITS_RE.sub(_mask_match, text)


def redact_payload(value: Any) -> Any:
    """Recursively redact sensitive keys and values in a JSON-like structure."""
    if isinstance(value, Mapping):
        redacted: dict[Any, Any] = {}
        for key, item in value.items():
            kind = _sensitive_kind(key)
            if kind is not None and isinstance(item, _CONTAINER_TYPES):
                redacted[key] = REDACTED
            elif kind == "mask":
                redacted[key] = mask_last4(item)
            elif kind == "redact":
                redacted[key] = REDACTED
            else:
                redacted[key] = redact_payload(item)
        return redacted

    if isinstance(value, (list, tuple, set, frozenset)):
        return [redact_payload(item) for item in value]

    if isinstance(value, str):
